#include "delimited_connector.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
static int push(sleela_delimited_row*r,const char*s,size_t n){char**f=(char**)realloc(r->fields,(r->count+1)*sizeof *f);if(!f)return 0;r->fields=f;r->fields[r->count]=(char*)malloc(n+1);if(!r->fields[r->count])return 0;memcpy(r->fields[r->count],s,n);r->fields[r->count][n]=0;r->count++;return 1;}
int sleela_delimited_parse(const char*line,char d,sleela_delimited_row*out,char*e,size_t es){if(!line||!out||(d!=','&&d!='\t'))return 0;memset(out,0,sizeof *out);if(e&&es)e[0]=0;size_t cap=strlen(line)+1;char*buf=(char*)malloc(cap);if(!buf)return 0;size_t n=0;int quoted=0,after=0;for(size_t i=0;;i++){char c=line[i];if(quoted){if(c=='"'&&line[i+1]=='"'){buf[n++]='"';i++;}else if(c=='"'){quoted=0;after=1;}else if(!c){if(e&&es)snprintf(e,es,"unterminated quoted field");free(buf);sleela_delimited_row_free(out);return 0;}else buf[n++]=c;continue;}if(after&&c!=d&&c!='\r'&&c!='\n'&&c!='\0'){if(e&&es)snprintf(e,es,"unexpected character after closing quote");free(buf);sleela_delimited_row_free(out);return 0;}if(c=='"'&&n==0&&!after){quoted=1;continue;}if(c=='"'){if(e&&es)snprintf(e,es,"quote inside unquoted field");free(buf);sleela_delimited_row_free(out);return 0;}if(c==d||c=='\r'||c=='\n'||!c){if(!push(out,buf,n)){free(buf);sleela_delimited_row_free(out);return 0;}n=0;after=0;if(!c||c=='\r'||c=='\n')break;continue;}buf[n++]=c;}free(buf);return 1;}
void sleela_delimited_row_free(sleela_delimited_row*r){if(!r)return;for(size_t i=0;i<r->count;i++)free(r->fields[i]);free(r->fields);memset(r,0,sizeof *r);}
